// app/dashboard/layout.js
export default function DashboardLayout({ children, analytics, team }) {
  return (
    <div>
      <nav>Sidebar</nav>
      <main>
        {children}
        <div className="panels">
          {analytics}
          {team}
        </div>
      </main>
    </div>
  );
}

// app/dashboard/@analytics/loading.js
